// QM-owned bespoke conformance checker for the "edit-commit re-entrancy" scantling.
//
// This is verification support, not a Captain-owned scantling file: it reads the REAL
// application source (js/app.js) and asserts a source-level structural invariant the
// scantling documents. No independent engine discharges this structural rule, so the
// Scantling agreement permits a bespoke checker owned by QM. The check is proven red by
// the current (buggy) source and turns green once Crew ends the editing session on commit.

const fs = require('fs');

// Extract a function body by name using brace matching. Returns the inner source of the
// function, or null when the function is not present.
function extractFunction(source, name) {
  const sig = 'function ' + name + '(';
  const start = source.indexOf(sig);
  if (start === -1) return null;
  const open = source.indexOf('{', start);
  if (open === -1) return null;
  let depth = 0;
  for (let i = open; i < source.length; i++) {
    if (source[i] === '{') depth++;
    else if (source[i] === '}') {
      depth--;
      if (depth === 0) return source.slice(open + 1, i);
    }
  }
  return null;
}

// An editing session is ended by removing the 'editing' class from the committed list item.
const REMOVE_EDITING = /li\s*\.classList\s*\.remove\s*\(\s*['"]editing['"]\s*\)/;

// Within commitEdit, every render() call must run AFTER the editing session is ended in
// its immediately enclosing block. A re-entrant blur arriving during/after the commit must
// therefore be a no-op instead of re-invoking the commit and double-removing the node.
function commitEditEndsSession(body) {
  const renderRe = /(^|[^.\w$])render\s*\(\s*\)/g;
  let m;
  const renders = [];
  while ((m = renderRe.exec(body)) !== null) renders.push(m.index);
  if (renders.length === 0) return false;

  // There must be at least one session-ending removal per render path.
  const removeCount = (body.match(REMOVE_EDITING) || []).length;
  if (removeCount < renders.length) return false;

  for (const pos of renders) {
    // Most recent unmatched '{' before the render marks the enclosing block start.
    let depth = 0;
    let blockStart = 0;
    for (let k = pos - 1; k >= 0; k--) {
      if (body[k] === '}') depth++;
      else if (body[k] === '{') {
        if (depth === 0) { blockStart = k + 1; break; }
        depth--;
      }
    }
    if (!REMOVE_EDITING.test(body.slice(blockStart, pos))) return false;
  }
  return true;
}

// Fallback guard: handleEditBlur refuses to re-invoke the commit once the edit is committed
// or the list item is already detached (it checks connectivity before re-invoking).
function handleEditBlurGuards(source) {
  const body = extractFunction(source, 'handleEditBlur');
  if (!body) return false;
  return /isConnected/.test(body) && /commitEdit/.test(body);
}

// Returns { ok, reason }. Reads the real application source and asserts the re-entrancy
// invariant from scantlings/edit-commit.json.
function checkEditCommitReentrancy(appScriptPath) {
  const source = fs.readFileSync(appScriptPath, 'utf8');
  const commitEdit = extractFunction(source, 'commitEdit');
  if (!commitEdit) {
    return { ok: false, reason: 'commitEdit function not found in ' + appScriptPath };
  }
  if (commitEditEndsSession(commitEdit)) return { ok: true };
  if (handleEditBlurGuards(source)) return { ok: true };
  return {
    ok: false,
    reason:
      'commitEdit leaves the editing session open before render() and handleEditBlur re-invokes ' +
      'commitEdit unguarded; a re-entrant blur can double-remove the list item node ' +
      '(edit-commit re-entrancy guard not discharged)',
  };
}

module.exports = { checkEditCommitReentrancy, extractFunction, commitEditEndsSession };

